import { lowPower } from "../animations/core/manager.js";
import { profile as p } from "../data/profile.js";
import { boot, pageHero, scene, lazyScene } from "./shared.js";
import { esc, heading } from "../components/utils.js";
import { timeline } from "../components/timeline.js";
import { init as initTimeline } from "../animations/timeline.js";
const d = p.diagrams.radiation;
boot(
  "about",
  `
 ${pageHero("about", `${scene("radiation", d.aria, "orbit-scene")}<div class="radiation-legend"><div><p class="radiation-label" data-pattern>${d.shapes[0]}</p><span class="diagram-hint">${d.hint}</span></div><div><div class="gain-legend"><span>${d.legend}</span><div><div class="gain-gradient"></div><div class="gain-ticks">${d.range.map((n) => `<span>${n}</span>`).join("")}</div></div></div></div></div><p class="diagram-caption mono">${d.caption}</p><p class="diagram-hint">${d.note}</p>`)}
 <section class="section container about-bio"><h2>${p.about.bioTitle}</h2><div class="bio-text">${p.about.paragraphs.map((text) => `<p>${esc(text)}</p>`).join("")}</div></section>
 <section class="section container">${heading(p.about.educationEyebrow, p.about.educationTitle)}${timeline(p.education)}</section>
 <section class="section container">${heading(p.about.skillsEyebrow, p.about.skillsTitle)}<div class="skills-grid">${p.skills.map((skill) => `<article class="skill-card"><h3>${esc(skill.group)}</h3><div class="skill-chips">${skill.items.map((item) => `<span class="skill-chip">${esc(item)}</span>`).join("")}</div></article>`).join("")}</div><div class="languages"><h3>${p.about.languagesTitle}</h3><p>${p.about.languages.join(" · ")}</p></div></section>
`,
);
lazyScene(
  "radiation",
  () =>
    lowPower
      ? import("../animations/radiationLite.js")
      : import("../animations/radiation.js"),
  "radiation",
);
initTimeline(document.querySelector("main"), {
  enabled: p.animations.timeline,
});
